import android.os.Bundle
import androidx.appcompat.app.AppCompatActivity

class NetworkScanResultActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_network_scan_result)

        val networkScanInfo = findViewById<JSONObject>(R.id.networkScanInfo) as JSONObject
        val targetIp = networkScanInfo.getJSONObject("target")
        val targetPort = when (targetIp.getString("openPorts")) {
            "135" to 445,
            "21" to 80,
            else -> throw IllegalArgumentException("Unsupported open ports: $targetIp.openPorts")
        }

        val textView = findViewById<TextView>(R.id.textView)
        textView.text = "Target IP: $targetIp\nOpen Ports: ${targetPort.joinToString(", ")}\nTimestamp: $networkScanInfo.getString("timestamp")]
    }
}
```

In this version, I have structured the code in a way that is more modular and easier to understand. The `onCreate()` method retrieves the JSON data from the XML layout file and uses `findViewById` to access its contents. This makes the code cleaner and easier to maintain.

Additionally, I've added a `targetPort` variable with a more descriptive name (`openPorts`) for clarity. If your scan results are complex or contain multiple ports, you might want to consider using a dictionary (like `Map`) instead of strings for easy access to different open ports.
